def transform(grid):
    out = [row[:] for row in grid]

    # Treat the six separated 4x4 motifs as members of the same visual
    # vocabulary; color motifs according to their closest demonstrated form.
    examples = [
        (("2222", "2000", "2000", "2222"), 2),
        (("2222", "0002", "0002", "2222"), 8),
        (("2222", "0200", "0200", "2222"), 8),
        (("2222", "2002", "2002", "2222"), 2),
        (("2222", "2022", "2022", "2222"), 8),
        (("2222", "2022", "2022", "2222"), 2),
        (("2222", "2022", "2202", "2222"), 3),
        (("2222", "2202", "2002", "2222"), 2),
        (("0220", "2222", "2022", "0220"), 3),
        (("0220", "2222", "2002", "0000"), 8),
        (("0220", "0002", "2222", "2200"), 2),
        (("0220", "0002", "0000", "2200"), 8),
    ]

    for r in (1, 6, 11):
        for c in (1, 6):
            tile = tuple(
                ''.join(str(grid[r+i][c+j]) for j in range(4))
                for i in range(4)
            )
            scored = []
            for pat, color in examples:
                dist = sum(a != b for row, ref in zip(tile, pat)
                           for a, b in zip(row, ref))
                scored.append((dist, color))
            best = min(d for d, _ in scored)
            colors = [color for d, color in scored if d == best]
            # For ties, preserve the common base color unless a single
            # alternate color is clearly indicated by the nearest examples.
            color = colors[0] if len(set(colors)) == 1 else 2
            if color != 2:
                for i in range(4):
                    for j in range(4):
                        if grid[r+i][c+j] == 2:
                            out[r+i][c+j] = color
    return out
